/**
 * 场景测试验证真实 DeathResolution 的标死→野孩子整波贡献→梦记录→遗言→晚 hook 顺序。
 * 输入为合法固定角色、原榜样选择、旧注入 duck HookRegistry 和字面狼刀；预期为手写状态／事件前缀。
 * 旧 registry 不提供新增整波方法，仍必须执行内建榜样转换；无完整游戏、模型或物理传输。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import { foxBoard } from "../../../support/features/cursed-fox/builders/scenario";
import { Role, Camp, Phase, DeathCause, type GameEvent } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../src/core/domain/components/names";
import { WildChildSetupWindow } from "../../../../src/game/mechanisms/roles/wild_child/setup";
import { getWildChildState } from "../../../../src/game/mechanisms/roles/wild_child/state";
import { DeathResolution } from "../../../../src/game/engine/death_resolution";
import { EventRegistry } from "../../../../src/game/engine/event_registry";
import type { HookRegistry } from "../../../../src/game/mechanisms/hooks/hook_registry";
import { DreamNightFrame } from "../../../../src/game/mechanisms/roles/dreamer/night_frame";
import { ToolGateway } from "../../../../src/game/gateway/tool_gateway";

test("mandatory committed-wave contributions survive a legacy custom hook registry before dream and last words", async () => {
  const roles = [Role.WildChild, Role.Wolf, Role.Wolf, Role.Seer, Role.Witch, Role.Hunter],
    { world, boardConfig: config } = bootstrapGame(foxBoard(roles), { fixedRoles: roles }),
    events: GameEvent[] = [],
    trace: string[] = [],
    gateway = new ToolGateway();
  expect(
    await new WildChildSetupWindow(world, gateway, events).execute(
      config,
      {
        async getAction() {
          return { name: "choose_wild_model", args: { target_id: 2 } };
        },
      },
      1,
      () => true,
    ),
  ).toBe(true);
  const legacyHooks = {
    onVotedOut() {
      return null;
    },
    async onDeath() {
      trace.push("late-hook");
      return { extraDeaths: [], extraDeathSources: {} };
    },
  } as unknown as HookRegistry;
  const resolver = new DeathResolution(
    world,
    events,
    gateway,
    new EventRegistry(legacyHooks),
    {
      day: 1,
      phase: Phase.Day,
      gameOver: false,
      result: null,
    },
    config,
  );
  const dreams = new DreamNightFrame([]);
  dreams.recordDeaths = () => {
    trace.push("dream");
    expect(world.getComponent(2, COMPONENT.Alive)?.alive).toBe(false);
    expect(world.getComponent(1, COMPONENT.Role)?.camp).toBe(Camp.Wolf);
    expect(events.some((event) => event.type === "wild_child_transformed")).toBe(true);
  };
  await resolver.resolve(
    [2],
    { 2: [DeathCause.WolfKill] },
    {
      async getAction() {
        trace.push("last-words");
        expect(getWildChildState(world.getComponent(1, COMPONENT.Role)!)?.status).toBe(
          "transformed",
        );
        return { name: "speak", args: { text: "literal last words" } };
      },
    },
    Phase.Night,
    Phase.Day,
    {},
    {
      dreams,
    },
  );
  expect(trace).toEqual(["dream", "last-words", "late-hook"]);
  const types = events.map((event) => event.type);
  expect(types).toContain("wild_child_model_eliminated");
  expect(types).toContain("last_words_granted");
  expect(types.indexOf("wild_child_model_eliminated")).toBeLessThan(
    types.indexOf("wild_child_transformed"),
  );
  expect(types.indexOf("wild_child_transformed")).toBeLessThan(types.indexOf("last_words_granted"));
});

/**
 * 单元测试验证开局组合的现场读取、构造失败前缀及 await 后取消短路。
 * 输入为真实空 World、真实盗贼牌库／野孩子绑定和手写抛错查询；输出依据字面轨迹与原状态。
 * 机制执行及 finally 关闭使用原 owner，不运行整局或模型，不用待测函数生成预期或模拟许可。
 */
import { expect, test, spyOn } from "bun:test";
import { Role, type GameEvent } from "@ai-werewolf-arena/game-contract";
import { World } from "../../../src/core/domain/world";
import { ToolGateway } from "../../../src/game/gateway/tool_gateway";
import { prepareGameSetup, type GameSetupRuntime } from "../../../src/rulesets/game-setup";
import {
  installInitialIdentityDeal,
  initialIdentitySetupReady,
} from "../../../src/game/mechanisms/roles/initial_identity/deal";
import { bootstrapGame } from "../../../src/app/bootstrap";
import {
  wildChildBinding,
  hasActiveWildChild,
} from "../../../src/game/mechanisms/roles/wild_child/lifecycle";
import { foxBoard } from "../../support/features/cursed-fox/builders/scenario";
import { WildChildSetupWindow } from "../../../src/game/mechanisms/roles/wild_child/setup-ports";

/** 测试调用方只消费组合交还的原窗口 Promise，完成值本身不再构成等待。 */
async function finishSetup(...args: Parameters<typeof prepareGameSetup>): Promise<boolean> {
  const sequence = prepareGameSetup(...args);
  let step = sequence.next();
  while (!step.done) step = sequence.next(await step.value);
  return step.value;
}

function unreadRuntime(world: World, trace: string[]): GameSetupRuntime {
  return {
    world() {
      trace.push("world");
      return world;
    },
    toolGateway() {
      trace.push("gateway");
      throw new Error("unexpected_gateway");
    },
    events() {
      trace.push("events");
      throw new Error("unexpected_events");
    },
    config() {
      trace.push("config");
      throw new Error("unexpected_config");
    },
  };
}

test("ready setup checks four live Worlds and does not call current at the successful tail", async () => {
  const trace: string[] = [];
  const ready = await finishSetup(
    unreadRuntime(new World(), trace),
    {
      async getAction() {
        throw new Error("unexpected_provider");
      },
    },
    1,
    () => {
      trace.push("current");
      return false;
    },
  );
  expect(ready).toBe(true);
  expect(trace).toEqual(["world", "world", "world", "world"]);
});

test("an initial constructor argument failure preserves only the earlier reads and pending deal", async () => {
  const world = new World(),
    trace: string[] = [],
    failure = new Error("original_gateway_failure");
  installInitialIdentityDeal(world, [Role.Villager, Role.Villager], []);
  const runtime = unreadRuntime(world, trace);
  runtime.toolGateway = () => {
    trace.push("gateway");
    throw failure;
  };
  await expect(
    finishSetup(
      runtime,
      {
        async getAction() {
          throw new Error("unexpected_provider");
        },
      },
      1,
      () => {
        trace.push("current");
        return true;
      },
    ),
  ).rejects.toBe(failure);
  expect(trace).toEqual(["world", "world", "gateway"]);
  expect(initialIdentitySetupReady(world)).toBe(false);
});

test("a real Wild Child cancellation stops after its own current check and preserves lifecycle closure", async () => {
  const roles = [Role.WildChild, Role.Wolf, Role.Wolf, Role.Seer, Role.Witch, Role.Hunter];
  const config = foxBoard(roles),
    game = bootstrapGame(config, { fixedRoles: roles });
  const trace: string[] = [],
    events: GameEvent[] = [],
    gateway = new ToolGateway();
  let active = true;
  const ready = await finishSetup(
    {
      world() {
        trace.push("world");
        return game.world;
      },
      toolGateway() {
        trace.push("gateway");
        return gateway;
      },
      events() {
        trace.push("events");
        return events;
      },
      config() {
        trace.push("config");
        return game.boardConfig;
      },
    },
    {
      async getAction() {
        trace.push("provider");
        active = false;
        return { name: "choose_wild_model", args: { target_id: 2 } };
      },
    },
    1,
    () => {
      trace.push("current");
      return active;
    },
  );
  expect(ready).toBe(false);
  // 原请求绑定也会复验当前性；取消后的窗口复验只读一次，组合的 OR 不再调用它。
  expect(trace).toEqual([
    "world",
    "world",
    "world",
    "gateway",
    "events",
    "config",
    "current",
    "current",
    "current",
    "provider",
    "current",
  ]);
  expect(wildChildBinding(game.world)?.setup).toBe("cancelled");
  expect(hasActiveWildChild(game.world)).toBe(false);
  expect(events).toEqual([]);
});

test("synchronous setup has no microtask boundary when every step is ready", async () => {
  const trace: string[] = [];
  queueMicrotask(() => trace.push("queued"));
  const sequence = prepareGameSetup(
    unreadRuntime(new World(), trace),
    {
      async getAction() {
        throw new Error("unexpected_provider");
      },
    },
    1,
    () => {
      trace.push("current");
      return true;
    },
  );
  expect(trace).toEqual([]);
  expect(sequence.next()).toEqual({ done: true, value: true });
  trace.push("complete");
  expect(trace).toEqual(["world", "world", "world", "world", "complete"]);
  await Promise.resolve();
  expect(trace.at(-1)).toBe("queued");
});

test("a yielded original window resumes guards synchronously without an extra completion Promise", async () => {
  const roles = [Role.WildChild, Role.Wolf, Role.Wolf, Role.Seer, Role.Witch, Role.Hunter];
  const game = bootstrapGame(foxBoard(roles), { fixedRoles: roles });
  const trace: string[] = [],
    events: GameEvent[] = [],
    gateway = new ToolGateway();
  const provider = {
    async getAction() {
      return null;
    },
  };
  const current = () => {
    trace.push("current");
    return true;
  };
  let release!: (value: boolean) => void;
  const originalPromise = new Promise<boolean>((resolve) => {
    release = resolve;
  });
  // 仅替换窗口结果来观察组合的暂停边界；不模拟选择规则、授权或库存提交。
  const spy = spyOn(WildChildSetupWindow.prototype, "execute").mockImplementation(function (
    this: WildChildSetupWindow,
    config,
    actualProvider,
    day,
    isCurrent,
  ) {
    trace.push("execute");
    expect(config).toBe(game.boardConfig);
    expect(actualProvider).toBe(provider);
    expect(day).toBe(1);
    expect(isCurrent).toBe(current);
    return originalPromise;
  });
  try {
    const sequence = prepareGameSetup(
      {
        world() {
          trace.push("world");
          return game.world;
        },
        toolGateway() {
          trace.push("gateway");
          return gateway;
        },
        events() {
          trace.push("events");
          return events;
        },
        config() {
          trace.push("config");
          return game.boardConfig;
        },
      },
      provider,
      1,
      current,
    );
    const step = sequence.next();
    expect(step.done).toBe(false);
    expect(step.value).toBe(originalPromise);
    expect(trace).toEqual(["world", "world", "world", "gateway", "events", "config", "execute"]);
    release(true);
    const ready = await originalPromise;
    queueMicrotask(() => trace.push("queued"));
    expect(sequence.next(ready)).toEqual({ done: true, value: true });
    trace.push("complete");
    expect(trace.slice(-4)).toEqual(["current", "world", "world", "complete"]);
    await Promise.resolve();
    expect(trace.at(-1)).toBe("queued");
  } finally {
    spy.mockRestore();
  }
});

controls.text:
/**
 * 负责拥有盗贼／变形者发到的卡、原手牌与首夜设置状态。
 * 输入为已安装阵容和明确选牌；输出为库存、设置状态和玩家 setup 数据副本。
 * 原 World 对应的 deal owner 持有手牌及参与者快照；关闭后保留选牌身份，后续角色替换
 * 不重新发库存，副本不授予 live 选择权限。
 */
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import { COMPONENT, type RoleComponent, Role, type World } from "../../../../core/domain";
export interface InitialIdentityCard {
  cardId: string;
  role: Role;
}
export type InitialIdentitySlot = 0 | 1;
export type InitialIdentitySetupStatus = "pending" | "complete" | "cancelled" | "failed";
export interface InitialIdentityDeal {
  readonly initialRoles: readonly Role[];
  readonly candidateCounts: ReadonlyMap<Role, number>;
  readonly hands: Map<number, InitialIdentityCard>;
  readonly reserve: [InitialIdentityCard, InitialIdentityCard];
  status: InitialIdentitySetupStatus;
  selection: { actorId: number; slot: InitialIdentitySlot | null; role: Role } | null;
}
export type InitialIdentityKind = "thief" | "shapeshifter";
export const INITIAL_IDENTITY_POLICIES = Object.freeze({
  thief: "lui_meme_thief_two_extra_villagers_v1",
  shapeshifter: "awa_netease_shapeshifter_two_extra_villagers_v1",
} as const);
interface DealOwner {
  kind: InitialIdentityKind;
  deal: InitialIdentityDeal;
  cards: readonly InitialIdentityCard[];
  initialCards: readonly InitialIdentityCard[];
  playerIds: readonly number[];
  hands: Map<number, InitialIdentityCard>;
  reserve: [InitialIdentityCard, InitialIdentityCard];
  status: InitialIdentitySetupStatus;
  selection: InitialIdentityDeal["selection"];
  selectionSnapshot: InitialIdentityDeal["selection"];
  players: InitialPlayer[];
}
interface InitialPlayer {
  id: number;
  role: RoleComponent;
  roleId: Role;
  camp: RoleComponent["camp"];
  state: RoleComponent["privateState"];
  life: NightLifeScope;
  campComponent: unknown;
  victory: unknown;
  victoryJson: string;
}
const owned = new WeakMap<World, DealOwner>();
const opened = new WeakSet<World>(),
  active = new WeakSet<World>();
function field(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && Object.hasOwn(d, "value") ? d.value : undefined;
}
export function readInitialIdentityCard(value: unknown): InitialIdentityCard | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const keys = Reflect.ownKeys(value);
  if (keys.length !== 2 || !keys.every((k) => k === "cardId" || k === "role")) return null;
  const cardId = field(value, "cardId"),
    role = field(value, "role");
  return typeof cardId === "string" &&
    /^deal:[0-9]+$/.test(cardId) &&
    Object.values(Role).includes(role as Role)
    ? { cardId, role: role as Role }
    : null;
}
function readSlot(
  reserve: [InitialIdentityCard, InitialIdentityCard],
  slot: InitialIdentitySlot,
): unknown {
  const d = Object.getOwnPropertyDescriptor(reserve, String(slot));
  return d && Object.hasOwn(d, "value") ? d.value : undefined;
}
export function installInitialIdentityDeal(
  world: World,
  roles: readonly Role[],
  playerIds: readonly number[],
  kind: InitialIdentityKind = "thief",
): void {
  if (kind !== "thief" && kind !== "shapeshifter") throw new Error("initial_identity_kind_invalid");
  if (owned.has(world) || roles.length !== playerIds.length + 2)
    throw new Error(`${kind}_initial_deal_invalid`);
  const cards = roles.map((role, i) => ({ cardId: `deal:${i}`, role }));
  const initialCards = Object.freeze(cards.map((card) => Object.freeze({ ...card }))),
    initialRoles = Object.freeze([...roles]);
  const candidateCounts = new Map<Role, number>();
  for (const role of roles) candidateCounts.set(role, (candidateCounts.get(role) ?? 0) + 1);
  const hands = new Map(playerIds.map((id, i) => [id, cards[i]!])),
    reserve: [InitialIdentityCard, InitialIdentityCard] = [
      cards[playerIds.length]!,
      cards[playerIds.length + 1]!,
    ];
  const deal: InitialIdentityDeal = {
    initialRoles,
    candidateCounts,
    hands,
    reserve,
    status: "pending",
    selection: null,
  };
  const players = playerIds.map((id) => {
    const role = world.getComponent(id, COMPONENT.Role)!,
      life = captureNightLife(world, id)!;
    return {
      id,
      role,
      roleId: role.role,
      camp: role.camp,
      state: role.privateState,
      life,
      campComponent: world.getComponent(id, COMPONENT.Camp),
      victory: world.getComponent(id, COMPONENT.Victory),
      victoryJson: JSON.stringify(copyEventData(world.getComponent(id, COMPONENT.Victory))),
    };
  });
  owned.set(world, {
    kind,
    deal,
    cards: Object.freeze([...cards]),
    initialCards,
    playerIds: Object.freeze([...playerIds]),
    hands,
    reserve,
    status: "pending",
    selection: null,
    selectionSnapshot: null,
    players,
  });
}
export function initialIdentityKind(world: World): InitialIdentityKind | undefined {
  return owned.get(world)?.kind;
}
function unavailable(world: World, suffix: string): Error {
  return new Error(`${initialIdentityKind(world) ?? "thief"}_${suffix}`);
}
export function initialIdentityStock(world: World): InitialIdentityDeal | undefined {
  return owned.get(world)?.deal;
}
export function initialIdentityDeal(world: World): readonly Role[] | undefined {
  return owned.get(world)?.initialCards.map((card) => card.role);
}
export function initialIdentityCandidateCounts(
  world: World,
): ReadonlyMap<Role, number> | undefined {
  const owner = owned.get(world);
  if (!owner) return;
  const counts = new Map<Role, number>();
  for (const card of owner.initialCards) counts.set(card.role, (counts.get(card.role) ?? 0) + 1);
  return counts;
}
export function initialIdentitySetupStatus(world: World): InitialIdentitySetupStatus | undefined {
  return owned.get(world)?.status;
}
export function hasActiveInitialIdentitySetup(world: World): boolean {
  return active.has(world);
}
export function initialIdentitySetupReady(world: World): boolean {
  return !owned.has(world) || owned.get(world)!.status === "complete";
}
export function pendingInitialIdentityDealValid(world: World): boolean {
  const o = owned.get(world);
  if (
    !o ||
    o.status !== "pending" ||
    field(o.deal, "hands") !== o.hands ||
    field(o.deal, "reserve") !== o.reserve
  )
    return false;
  if (
    world.entityIds().length !== o.playerIds.length ||
    !o.players.every(
      (p) =>
        livingNightLife(world, p.life) &&
        world.getComponent(p.id, COMPONENT.Role) === p.role &&
        field(p.role, "role") === p.roleId &&
        field(p.role, "camp") === p.camp &&
        field(p.role, "privateState") === p.state &&
        world.getComponent(p.id, COMPONENT.Camp) === p.campComponent &&
        field(p.campComponent, "camp") === p.camp &&
        world.getComponent(p.id, COMPONENT.Victory) === p.victory,
    )
  )
    return false;
  try {
    if (o.players.some((p) => JSON.stringify(copyEventData(p.victory)) !== p.victoryJson))
      return false;
  } catch {
    return false;
  }
  const size = Object.getOwnPropertyDescriptor(Map.prototype, "size")!.get!.call(o.hands);
  if (size !== o.playerIds.length || o.reserve.length !== 2) return false;
  for (let i = 0; i < o.cards.length; i++) {
    const card = o.cards[i]!,
      data = readInitialIdentityCard(card),
      original = o.initialCards[i]!;
    if (!data || data.cardId !== original.cardId || data.role !== original.role) return false;
    const current =
      i < o.playerIds.length
        ? Map.prototype.get.call(o.hands, o.playerIds[i]!)
        : readSlot(o.reserve, (i - o.playerIds.length) as InitialIdentitySlot);
    if (current !== card) return false;
  }
  return true;
}
export function openInitialIdentitySetup(world: World): InitialIdentityDeal {
  const o = owned.get(world);
  if (!o || o.status !== "pending" || opened.has(world) || active.has(world))
    throw unavailable(world, "setup_unavailable");
  opened.add(world);
  active.add(world);
  return o.deal;
}
export function closeInitialIdentitySetup(
  world: World,
  status: Exclude<InitialIdentitySetupStatus, "pending">,
): void {
  active.delete(world);
  const o = owned.get(world);
  if (!o) return;
  o.status = status;
  const d = Object.getOwnPropertyDescriptor(o.deal, "status");
  if (d && Object.hasOwn(d, "value") && d.writable)
    try {
      Object.defineProperty(o.deal, "status", { ...d, value: status });
    } catch {
      /* Authority closes even with corrupted storage. */
    }
}
export function selectInitialIdentityCard(
  world: World,
  actorId: number,
  slot: InitialIdentitySlot | null,
): Role {
  const o = owned.get(world);
  if (!o || !hasActiveInitialIdentitySetup(world) || !pendingInitialIdentityDealValid(world))
    throw unavailable(world, "selection_unavailable");
  const original = Map.prototype.get.call(o.hands, actorId) as InitialIdentityCard;
  if (
    o.kind === "shapeshifter" &&
    (slot === null ||
      (slot !== 0 && slot !== 1) ||
      readInitialIdentityCard(original)?.role !== Role.Shapeshifter ||
      (o.reserve.some((card) => readInitialIdentityCard(card)?.role === Role.Wolf) &&
        readInitialIdentityCard(readSlot(o.reserve, slot))?.role !== Role.Wolf))
  )
    throw unavailable(world, "selection_invalid");
  const chosen = slot === null ? original : (readSlot(o.reserve, slot) as InitialIdentityCard);
  if (slot !== null) {
    Map.prototype.set.call(o.hands, actorId, chosen);
    o.reserve[slot] = original;
  }
  const selection = { actorId, slot, role: chosen.role };
  o.selection = selection;
  o.selectionSnapshot = Object.freeze({ ...selection });
  o.deal.selection = selection;
  return chosen.role;
}
export function projectInitialIdentitySetup(world: World) {
  const o = owned.get(world);
  if (!o) return;
  if (
    field(o.deal, "hands") !== o.hands ||
    field(o.deal, "reserve") !== o.reserve ||
    o.reserve.length !== 2
  )
    return;
  const hands = o.playerIds.map((actorId) => ({
      actorId,
      card: Map.prototype.get.call(o.hands, actorId) as unknown,
    })),
    reserves = [readSlot(o.reserve, 0), readSlot(o.reserve, 1)];
  const raw = [...hands.map((row) => row.card), ...reserves];
  if (
    raw.length !== o.cards.length ||
    new Set(raw).size !== o.cards.length ||
    raw.some((card) => !o.cards.includes(card as InitialIdentityCard))
  )
    return;
  const data = raw.map(readInitialIdentityCard);
  if (data.some((card) => !card)) return;
  for (const card of data)
    if (!o.initialCards.some((c) => c.cardId === card!.cardId && c.role === card!.role)) return;
  const selection = field(o.deal, "selection");
  if (selection !== o.selection) return;
  if (
    selection &&
    (!o.selectionSnapshot ||
      Reflect.ownKeys(selection as object).length !== 3 ||
      ["actorId", "slot", "role"].some(
        (key) => field(selection, key) !== field(o.selectionSnapshot, key),
      ))
  )
    return;
  const selected = o.selectionSnapshot;
  const selectedIndex = selected ? o.playerIds.indexOf(selected.actorId) : -1;
  for (let i = 0; i < o.playerIds.length; i++) {
    const expected =
      selectedIndex === i && selected?.slot !== null && selected?.slot !== undefined
        ? o.cards[o.playerIds.length + selected.slot]
        : o.cards[i];
    if (raw[i] !== expected) return;
  }
  for (const slot of [0, 1] as const) {
    const expected =
      selected?.slot === slot ? o.cards[selectedIndex] : o.cards[o.playerIds.length + slot];
    if (reserves[slot] !== expected) return;
  }
  return {
    policy: INITIAL_IDENTITY_POLICIES[o.kind],
    status: o.status,
    hands: hands.map((row, i) => ({ actorId: row.actorId, ...data[i]! })),
    reserve: data.slice(hands.length) as [InitialIdentityCard, InitialIdentityCard],
    selection: o.selectionSnapshot ? { ...o.selectionSnapshot } : null,
  };
}

const activeNights = new WeakSet<World>(),
  committedNights = new WeakMap<World, Set<number>>();
export function hasActiveInitialIdentityNight(world: World): boolean {
  return activeNights.has(world);
}
export function hasInitialIdentityNightCommit(world: World, day: number): boolean {
  return committedNights.get(world)?.has(day) === true;
}
export function openInitialIdentityNight(world: World, day: number): () => void {
  if (!owned.has(world)) return () => {};
  if (
    !initialIdentitySetupReady(world) ||
    hasActiveInitialIdentitySetup(world) ||
    activeNights.has(world) ||
    committedNights.get(world)?.has(day)
  )
    throw unavailable(world, "night_reentry_or_unready");
  let days = committedNights.get(world);
  if (!days) {
    days = new Set();
    committedNights.set(world, days);
  }
  days.add(day);
  activeNights.add(world);
  return () => {
    activeNights.delete(world);
  };
}

import { Role, type RoleComponent, type ToolCall } from "../../../../core/domain";
import { getThiefState, readThiefTool } from "../thief/state";
import { getShapeshifterState, readShapeshifterTool } from "../shapeshifter/state";
import {
  INITIAL_IDENTITY_POLICIES,
  type InitialIdentityKind,
  type InitialIdentitySlot,
} from "./deal";
export type InitialIdentityState =
  | NonNullable<ReturnType<typeof getThiefState>>
  | NonNullable<ReturnType<typeof getShapeshifterState>>;
export const initialIdentityPolicy = (kind: InitialIdentityKind) => INITIAL_IDENTITY_POLICIES[kind];
export const initialIdentityRole = (kind: InitialIdentityKind) =>
  kind === "thief" ? Role.Thief : Role.Shapeshifter;
export const initialIdentityTool = (kind: InitialIdentityKind) =>
  kind === "thief" ? ("choose_thief_card" as const) : ("choose_shapeshifter_card" as const);
export const getInitialIdentityState = (
  role: RoleComponent | undefined,
  kind: InitialIdentityKind,
): InitialIdentityState | null =>
  kind === "thief" ? getThiefState(role) : getShapeshifterState(role);
export const readInitialIdentityTool = (call: ToolCall, kind: InitialIdentityKind) =>
  kind === "thief" ? readThiefTool(call) : readShapeshifterTool(call);
export function initialIdentityChoiceRule(
  kind: InitialIdentityKind,
  roles: readonly Role[],
): { mustChoose: boolean; allowedSlots: readonly InitialIdentitySlot[] } {
  const wolfSlots = roles.flatMap((role, slot) =>
    role === Role.Wolf ? [slot as InitialIdentitySlot] : [],
  );
  return Object.freeze({
    mustChoose: kind === "shapeshifter" || wolfSlots.length === 2,
    allowedSlots: Object.freeze(
      kind === "shapeshifter" && wolfSlots.length ? wolfSlots : ([0, 1] as InitialIdentitySlot[]),
    ),
  });
}

/**
 * 负责野孩子榜样选择、参与者快照与转阵营生命周期。输入为原 World 组件和首夜请求；
 * 仅通过仍当前的局部窗口写选择绑定及榜样死亡后的转换。组件替换或选择关闭撤销局部
 * 权限，截止时间别名仍保留原检查。
 */
import { createCampComponent } from "../../../observation/component-presentation";
import type { WildChildState, WildChildReadState } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { registerRequestAliasPropagation } from "../../../../core/domain/request_delivery";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import { COMPONENT, Camp, Role, Phase, createVictoryComponent, type World, type ActionRequest, type RoleComponent, type CampComponent, type VictoryComponent, type GameEvent, type DeathSources } from "../../../../core/domain";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import { captureDebateParticipant, type DebateParticipant } from "../debater/authority";
import { freshWildChildState, getWildChildState } from "./state";
export interface WildChildBinding {
  world: World;
  actorId: number;
  actor: DebateParticipant;
  state: WildChildReadState;
  config: ReadonlyBoardConfig;
  configJson: string;
  camp: CampComponent;
  victory: VictoryComponent;
  expectedState: string;
  victoryJson: string;
  model: NightLifeScope | null;
  setup: "pending" | "active" | "complete" | "failed" | "cancelled";
  actorDeath: boolean;
  modelDeath: boolean;
  modelCommitted: boolean;
}
const bindings = new WeakMap<World, WildChildBinding>();
const nights = new WeakMap<World, Set<number>>();
const activeNights = new WeakSet<World>();
const requests = new WeakMap<
  ActionRequest,
  { binding: WildChildBinding; context: ActionRequest["context"] }
>();
const windows = new WeakMap<
  World,
  { isCurrent: () => boolean; targets: Map<number, DebateParticipant> }
>();
function safeJson(value: unknown): string {
  try {
    return JSON.stringify(copyEventData(value));
  } catch {
    return "invalid";
  }
}
export function installWildChild(world: World, config: ReadonlyBoardConfig): void {
  if (bindings.has(world)) throw new Error("wild_child_already_installed");
  const actorId = world
    .entityIds()
    .find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.WildChild);
  if (actorId === undefined) return;
  const actor = captureDebateParticipant(world, actorId)!;
  const state = getWildChildState(actor.role)!;
  const camp = world.getComponent(actorId, COMPONENT.Camp)!;
  const victory = world.getComponent(actorId, COMPONENT.Victory)!;
  bindings.set(world, {
    world,
    actorId,
    actor,
    state,
    config,
    configJson: safeJson(config),
    camp,
    victory,
    expectedState: safeJson(state),
    victoryJson: safeJson(victory),
    model: null,
    setup: "pending",
    actorDeath: false,
    modelDeath: false,
    modelCommitted: false,
  });
}
export function wildChildBinding(world: World): WildChildBinding | undefined {
  return bindings.get(world);
}
function ownData(value: object, key: string): unknown {
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && Object.hasOwn(d, "value") ? d.value : undefined;
}
function captureChoiceTarget(world: World, id: number): DebateParticipant | null {
  const life = captureNightLife(world, id),
    role = world.getComponent(id, COMPONENT.Role);
  if (!life || !role) return null;
  const roleId = ownData(role, "role"),
    camp = ownData(role, "camp"),
    state = ownData(role, "privateState");
  if (typeof roleId !== "string" || typeof camp !== "string" || !state || typeof state !== "object")
    return null;
  return {
    life,
    role,
    roleId: roleId as RoleComponent["role"],
    camp: camp as RoleComponent["camp"],
    state: state as RoleComponent["privateState"],
  };
}
function sameChoiceTarget(world: World, snapshot: DebateParticipant): boolean {
  return (
    livingNightLife(world, snapshot.life) &&
    world.getComponent(snapshot.life.id, COMPONENT.Role) === snapshot.role &&
    ownData(snapshot.role, "role") === snapshot.roleId &&
    ownData(snapshot.role, "camp") === snapshot.camp &&
    ownData(snapshot.role, "privateState") === snapshot.state
  );
}
function validWildChildIdentity(b: WildChildBinding): boolean {
  return (
    bindings.get(b.world) === b &&
    b.world.getComponent(b.actorId, COMPONENT.Role) === b.actor.role &&
    ownData(b.actor.role, "role") === Role.WildChild &&
    ownData(b.actor.role, "camp") === b.actor.camp &&
    ownData(b.actor.role, "privateState") === b.actor.state &&
    ownData(b.actor.state, "wildChild") === b.state &&
    safeJson(b.state) !== "invalid" &&
    safeJson(b.state) === b.expectedState &&
    b.world.getComponent(b.actorId, COMPONENT.Camp) === b.camp &&
    ownData(b.camp, "camp") === b.actor.camp &&
    b.world.getComponent(b.actorId, COMPONENT.Victory) === b.victory &&
    safeJson(b.victory) !== "invalid" &&
    safeJson(b.victory) === b.victoryJson &&
    safeJson(b.config) !== "invalid" &&
    safeJson(b.config) === b.configJson
  );
}
export function validWildChildOwner(b: WildChildBinding): boolean {
  return validWildChildIdentity(b) && livingNightLife(b.world, b.actor.life);
}
export function projectWildChild(
  world: World,
  role: RoleComponent,
): WildChildReadState | undefined {
  const b = bindings.get(world);
  if (!b || b.actor.role !== role) return undefined;
  if (!validWildChildOwner(b)) return { ...freshWildChildState(), remaining: 0, status: "closed" };
  return structuredClone(b.state);
}
export function wildChildReady(world: World): boolean {
  const b = bindings.get(world);
  return !b || b.setup === "complete";
}
export function hasActiveWildChild(world: World): boolean {
  return bindings.get(world)?.setup === "active" || activeNights.has(world);
}
export function hasWildChildNightCommit(world: World, day: number): boolean {
  return nights.get(world)?.has(day) ?? false;
}
export function openWildChildChoice(b: WildChildBinding, isCurrent: () => boolean): void {
  if (b.setup !== "pending" || !validWildChildOwner(b))
    throw new Error("wild_child_setup_unavailable");
  b.setup = "active";
  windows.set(b.world, {
    isCurrent,
    targets: new Map(
      b.world
        .getAliveEntityIds()
        .filter((id) => id !== b.actorId)
        .map((id) => [id, captureChoiceTarget(b.world, id)!]),
    ),
  });
}
export function validWildChildChoice(b: WildChildBinding): boolean {
  const w = windows.get(b.world);
  return (
    !!w &&
    w.isCurrent() &&
    b.setup === "active" &&
    validWildChildOwner(b) &&
    b.state.status === "pending" &&
    b.state.remaining === 1 &&
    b.state.choice === null &&
    [...w.targets.values()].every((p) => !!p && sameChoiceTarget(b.world, p))
  );
}
export function authorizedWildChild(
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
): boolean {
  const b = bindings.get(world);
  return (
    !!b &&
    b === scope &&
    actorId === b.actorId &&
    day === 1 &&
    phase === Phase.Night &&
    validWildChildChoice(b)
  );
}
export function bindWildChildRequest(world: World, request: ActionRequest): void {
  const b = bindings.get(world);
  if (
    b &&
    request.context.stage === "wild_child" &&
    request.phase === Phase.Night &&
    request.context.day === 1 &&
    request.actorId === b.actorId &&
    validWildChildChoice(b)
  ) {
    requests.set(request, { binding: b, context: request.context });
    registerRequestAliasPropagation(request, 30, inheritWildChildDeadlineRequest);
  }
}
export function wildChildRequestScope(
  world: World,
  request: ActionRequest,
): WildChildBinding | undefined {
  const a = requests.get(request);
  return a &&
    a.binding.world === world &&
    request.actorId === a.binding.actorId &&
    request.context === a.context &&
    request.context.stage === "wild_child" &&
    request.context.day === 1 &&
    request.phase === Phase.Night &&
    validWildChildChoice(a.binding)
    ? a.binding
    : undefined;
}
export function inheritWildChildDeadlineRequest(
  source: ActionRequest,
  target: ActionRequest,
): void {
  const b = requests.get(source);
  if (!b || !wildChildRequestScope(b.binding.world, source)) return;
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  if (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && Reflect.get(source, k) === Reflect.get(target, k))
  ) {
    requests.set(target, b);
    registerRequestAliasPropagation(target, 30, inheritWildChildDeadlineRequest);
  }
}
export function commitWildChildChoice(b: WildChildBinding, targetId: number): boolean {
  const target = windows.get(b.world)?.targets.get(targetId);
  if (!validWildChildChoice(b) || !target || !sameChoiceTarget(b.world, target)) return false;
  const choice = { day: 1 as const, targetId };
  if (
    !["remaining", "status", "choice"].every(
      (k) => Object.getOwnPropertyDescriptor(b.state, k)?.writable,
    )
  )
    return false;
  (b.state as Pick<WildChildState, "remaining">).remaining = 0;
  (b.state as Pick<WildChildState, "status">).status = "chosen";
  (b.state as Pick<WildChildState, "choice">).choice = choice;
  b.model = target.life;
  b.expectedState = safeJson(b.state);
  b.setup = "complete";
  windows.delete(b.world);
  return true;
}
export function closeWildChildChoice(b: WildChildBinding, status: "failed" | "cancelled"): void {
  if (b.setup === "complete") return;
  b.setup = status;
  windows.delete(b.world);
  if (["remaining", "status"].every((k) => Object.getOwnPropertyDescriptor(b.state, k)?.writable)) {
    (b.state as Pick<WildChildState, "remaining">).remaining = 0;
    (b.state as Pick<WildChildState, "status">).status = "closed";
    b.expectedState = safeJson(b.state);
  }
}
/** 紧邻实际引擎 Alive 提交之前调用，不由查询或原始拟议目标调用。 */
export function recordWildChildDeathCommit(world: World, id: number): void {
  const b = bindings.get(world);
  if (!b || !validWildChildIdentity(b)) return;
  if (id === b.actorId && livingNightLife(world, b.actor.life)) b.actorDeath = true;
  if (
    b.setup === "complete" &&
    !b.modelCommitted &&
    b.state.status === "chosen" &&
    b.model?.id === id &&
    livingNightLife(world, b.model)
  )
    b.modelDeath = true;
}
/** 调用前标记完整 pending 死亡波；后续射击波独立提交。 */
export function resolveWildChildDeathWave(
  world: World,
  ids: readonly number[],
  sources: DeathSources,
  day: number,
  phase: Phase,
  events: GameEvent[],
): void {
  const b = bindings.get(world),
    model = b?.model;
  if (
    !b ||
    !model ||
    !b.modelDeath ||
    b.modelCommitted ||
    !ids.includes(model.id) ||
    world.getComponent(model.id, COMPONENT.Alive) !== model.life ||
    model.life.alive ||
    aliveLifeVersion(model.life) !== model.version + 1
  )
    return;
  b.modelCommitted = true;
  const deathCommit = `wild-model:${b.actorId}:${model.id}:${day}`;
  events.push({
    timestamp: Date.now(),
    type: "wild_child_model_eliminated",
    payload: {
      actorId: b.actorId,
      targetId: model.id,
      day,
      phase,
      deathCommit,
      sources: [...(sources[model.id] ?? [])],
      deadIds: [...ids],
    },
  });
  if (
    !validWildChildOwner(b) ||
    b.state.status !== "chosen" ||
    b.actor.camp !== Camp.Good ||
    !["status", "eligibleNight"].every(
      (k) => Object.getOwnPropertyDescriptor(b.state, k)?.writable,
    ) ||
    !Object.getOwnPropertyDescriptor(b.actor.role, "camp")?.writable
  )
    return;
  const camp = createCampComponent(Camp.Wolf, world.locale),
    victory = createVictoryComponent([{ kind: "faction", faction: Camp.Wolf }]);
  b.actor.role.camp = Camp.Wolf;
  world.addComponent(b.actorId, COMPONENT.Camp, camp);
  world.addComponent(b.actorId, COMPONENT.Victory, victory);
  b.actor.camp = Camp.Wolf;
  b.camp = camp;
  b.victory = victory;
  b.victoryJson = safeJson(victory);
  (b.state as Pick<WildChildState, "status">).status = "transformed";
  (b.state as Pick<WildChildState, "eligibleNight">).eligibleNight = day + 1;
  b.expectedState = safeJson(b.state);
  events.push({
    timestamp: Date.now(),
    type: "wild_child_transformed",
    payload: { actorId: b.actorId, day, eligibleNight: day + 1, camp: Camp.Wolf, deathCommit },
  });
}
export function wildChildPackKnown(role: RoleComponent, world?: World): boolean {
  const b = world && bindings.get(world);
  if (
    !b ||
    b.actor.role !== role ||
    !validWildChildIdentity(b) ||
    b.setup !== "complete" ||
    b.state.status !== "active"
  )
    return false;
  return (
    livingNightLife(b.world, b.actor.life) ||
    (b.actorDeath &&
      b.world.getComponent(b.actorId, COMPONENT.Alive) === b.actor.life.life &&
      !b.actor.life.life.alive &&
      aliveLifeVersion(b.actor.life.life) === b.actor.life.version + 1)
  );
}
export function wildChildPackActive(role: RoleComponent, world?: World): boolean {
  const b = world && bindings.get(world);
  return !!b && wildChildPackKnown(role, world) && validWildChildOwner(b);
}
export function openWildChildNight(world: World, day: number, events: GameEvent[]): () => void {
  const b = bindings.get(world);
  if (!b) return () => {};
  if (hasActiveWildChild(world) || hasWildChildNightCommit(world, day) || !wildChildReady(world))
    throw new Error("wild_child_night_unavailable");
  const days = nights.get(world) ?? new Set<number>();
  days.add(day);
  nights.set(world, days);
  activeNights.add(world);
  try {
    if (
      validWildChildOwner(b) &&
      b.state.status === "transformed" &&
      b.state.eligibleNight !== null &&
      day >= b.state.eligibleNight &&
      ["status", "activeFromNight"].every(
        (k) => Object.getOwnPropertyDescriptor(b.state, k)?.writable,
      )
    ) {
      (b.state as Pick<WildChildState, "status">).status = "active";
      (b.state as Pick<WildChildState, "activeFromNight">).activeFromNight = day;
      b.expectedState = safeJson(b.state);
      events.push({
        timestamp: Date.now(),
        type: "wild_child_pack_activated",
        payload: { actorId: b.actorId, day, eligibleNight: b.state.eligibleNight },
      });
    }
  } catch (error) {
    activeNights.delete(world);
    throw error;
  }
  return () => {
    activeNights.delete(world);
  };
}

/**
 * 负责孤独少女的首夜选择绑定、复制阵营与已选目标生命，拥有该关系的原参与者记录。
 * 输入为原 World 参与者和首夜请求；输出为已接受选择和后续目标死亡结算。
 * 不变量：仅在原身份／资源仍匹配时写入；关闭或替换参与者使 scope 失效，包括期限别名。
 * 失败窗口审计保留原授权身份，不读取外来 accessor 或恢复已消耗库存。
 */
import type { LonelyGirlState, LonelyGirlReadState } from "@ai-werewolf-arena/game-contract";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { registerRequestAliasPropagation } from "../../../../core/domain/request_delivery";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Camp,
  Role,
  Phase,
  createVictoryComponent,
  type World,
  type ActionRequest,
  type RoleComponent,
  type CampComponent,
  type VictoryComponent,
} from "../../../../core/domain";
import { aliveLifeVersion, type AliveComponent } from "../../../../core/domain/components/alive";
import { freshLonelyGirlState, getLonelyGirlState, LONELY_GIRL_POLICY, lonelyData } from "./state";
interface Participant {
  id: number;
  life: AliveComponent;
  version: number;
  alive: PropertyDescriptor;
  role: RoleComponent;
  kind: Role;
  roleCamp: Camp;
  state: RoleComponent["privateState"];
  camp: CampComponent;
  campValue: Camp;
  privateSnapshot: Record<string, unknown>;
}
export interface LonelyGirlBinding {
  world: World;
  actorId: number;
  actor: Participant;
  participants: ReadonlyMap<number, Participant>;
  state: LonelyGirlReadState;
  config: ReadonlyBoardConfig;
  configJson: string;
  victory: VictoryComponent;
  affiliations: VictoryComponent["affiliations"];
  status: "pending" | "active" | "complete" | "failed" | "cancelled";
  choice: LonelyGirlReadState["choice"];
  membership: Camp | null;
  isCurrent: (() => boolean) | null;
}
const bindings = new WeakMap<World, LonelyGirlBinding>(),
  requests = new WeakMap<
    ActionRequest,
    { binding: LonelyGirlBinding; context: ActionRequest["context"] }
  >(),
  nights = new WeakMap<World, Set<number>>(),
  activeNights = new WeakSet<World>();
function safeJson(value: unknown): string | null {
  try {
    const p = copyEventData(value);
    return p === null ? null : JSON.stringify(p);
  } catch {
    return null;
  }
}
function capture(world: World, id: number): Participant | null {
  const life = world.getComponent(id, COMPONENT.Alive),
    role = world.getComponent(id, COMPONENT.Role),
    camp = world.getComponent(id, COMPONENT.Camp),
    version = life && aliveLifeVersion(life),
    alive = life && Object.getOwnPropertyDescriptor(life, "alive"),
    kind = lonelyData(role, "role"),
    roleCamp = lonelyData(role, "camp"),
    state = lonelyData(role, "privateState"),
    campValue = lonelyData(camp, "camp");
  if (
    !life ||
    version === undefined ||
    !alive ||
    life.alive !== true ||
    !role ||
    !camp ||
    typeof kind !== "string" ||
    !state ||
    typeof state !== "object" ||
    ![Camp.Good, Camp.Wolf].includes(roleCamp as Camp) ||
    campValue !== roleCamp
  )
    return null;
  return {
    id,
    life,
    version,
    alive,
    role,
    kind: kind as Role,
    roleCamp: roleCamp as Camp,
    state: state as RoleComponent["privateState"],
    camp,
    campValue: campValue as Camp,
    privateSnapshot: structuredClone(state) as Record<string, unknown>,
  };
}
function same(world: World, p: Participant): boolean {
  const d = Object.getOwnPropertyDescriptor(p.life, "alive");
  return (
    world.getComponent(p.id, COMPONENT.Alive) === p.life &&
    aliveLifeVersion(p.life) === p.version &&
    !!d &&
    d.get === p.alive.get &&
    d.set === p.alive.set &&
    d.value === p.alive.value &&
    p.life.alive === true &&
    world.getComponent(p.id, COMPONENT.Role) === p.role &&
    lonelyData(p.role, "role") === p.kind &&
    lonelyData(p.role, "camp") === p.roleCamp &&
    lonelyData(p.role, "privateState") === p.state &&
    world.getComponent(p.id, COMPONENT.Camp) === p.camp &&
    lonelyData(p.camp, "camp") === p.campValue
  );
}
export function installLonelyGirl(world: World, config: ReadonlyBoardConfig): void {
  if (bindings.has(world)) throw new Error("lonely_girl_already_installed");
  const actorId = world
    .entityIds()
    .find((id) => lonelyData(world.getComponent(id, COMPONENT.Role), "role") === Role.LonelyGirl);
  if (actorId === undefined) return;
  const participants = new Map(world.entityIds().map((id) => [id, capture(world, id)] as const)),
    actor = participants.get(actorId),
    state = getLonelyGirlState(actor?.role),
    victory = world.getComponent(actorId, COMPONENT.Victory),
    affiliations = lonelyData(victory, "affiliations"),
    configJson = safeJson(config);
  if (
    !actor ||
    !state ||
    !victory ||
    !Array.isArray(affiliations) ||
    safeJson(affiliations) !== "[]" ||
    !configJson ||
    [...participants.values()].some((p) => !p)
  )
    throw new Error("lonely_girl_initial_state_invalid");
  bindings.set(world, {
    world,
    actorId,
    actor,
    participants: participants as Map<number, Participant>,
    state,
    config,
    configJson,
    victory,
    affiliations,
    status: "pending",
    choice: null,
    membership: null,
    isCurrent: null,
  });
}
export function lonelyGirlBinding(world: World): LonelyGirlBinding | undefined {
  return bindings.get(world);
}
function pendingOwner(b: LonelyGirlBinding): boolean {
  const rem = Object.getOwnPropertyDescriptor(b.state, "remaining"),
    choice = Object.getOwnPropertyDescriptor(b.state, "choice");
  return (
    bindings.get(b.world) === b &&
    b.participants.size === b.world.entityIds().length &&
    [...b.participants.values()].every((p) => same(b.world, p)) &&
    b.actor.kind === Role.LonelyGirl &&
    b.actor.roleCamp === Camp.Good &&
    getLonelyGirlState(b.actor.role) === b.state &&
    rem?.value === 1 &&
    rem.writable === true &&
    choice?.value === null &&
    choice.writable === true &&
    b.world.getComponent(b.actorId, COMPONENT.Victory) === b.victory &&
    lonelyData(b.victory, "affiliations") === b.affiliations &&
    safeJson(b.affiliations) === "[]" &&
    safeJson(b.config) === b.configJson
  );
}
export function lonelyGirlReady(world: World): boolean {
  const b = bindings.get(world);
  return b
    ? b.status === "complete"
    : !world
        .entityIds()
        .some(
          (id) => lonelyData(world.getComponent(id, COMPONENT.Role), "role") === Role.LonelyGirl,
        );
}
export function hasActiveLonelyGirl(world: World): boolean {
  return bindings.get(world)?.status === "active" || activeNights.has(world);
}
export function hasLonelyGirlNightCommit(world: World, day: number): boolean {
  return nights.get(world)?.has(day) ?? false;
}
export function openLonelyGirlChoice(b: LonelyGirlBinding, isCurrent: () => boolean): boolean {
  if (b.status !== "pending") throw new Error("lonely_girl_setup_unavailable");
  b.status = "active";
  b.isCurrent = isCurrent;
  return validLonelyGirlChoice(b);
}
export function validLonelyGirlChoice(b: LonelyGirlBinding): boolean {
  return b.status === "active" && b.isCurrent?.() === true && pendingOwner(b);
}
export function authorizedLonelyGirl(
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
): boolean {
  const b = bindings.get(world);
  return (
    !!b &&
    b === scope &&
    b.actorId === actorId &&
    day === 1 &&
    phase === Phase.Night &&
    validLonelyGirlChoice(b)
  );
}
export function bindLonelyGirlRequest(world: World, request: ActionRequest): void {
  const b = bindings.get(world);
  if (
    b &&
    request.actorId === b.actorId &&
    request.phase === Phase.Night &&
    request.context.stage === "lonely_girl" &&
    request.context.day === 1 &&
    validLonelyGirlChoice(b)
  ) {
    requests.set(request, { binding: b, context: request.context });
    registerRequestAliasPropagation(request, 40, inheritLonelyGirlDeadlineRequest);
  }
}
export function lonelyGirlRequestScope(
  world: World,
  request: ActionRequest,
): LonelyGirlBinding | undefined {
  const a = requests.get(request);
  return a &&
    a.binding.world === world &&
    request.actorId === a.binding.actorId &&
    request.phase === Phase.Night &&
    request.context === a.context &&
    request.context.stage === "lonely_girl" &&
    request.context.day === 1 &&
    validLonelyGirlChoice(a.binding)
    ? a.binding
    : undefined;
}
export function inheritLonelyGirlDeadlineRequest(
  source: ActionRequest,
  target: ActionRequest,
): void {
  const a = requests.get(source);
  if (!a || !lonelyGirlRequestScope(a.binding.world, source)) return;
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  if (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && (source as any)[k] === (target as any)[k])
  ) {
    requests.set(target, a);
    registerRequestAliasPropagation(target, 40, inheritLonelyGirlDeadlineRequest);
  }
}
export function commitLonelyGirlChoice(b: LonelyGirlBinding, targetId: number): Camp | null {
  const target = b.participants.get(targetId);
  if (!target || targetId === b.actorId || !validLonelyGirlChoice(b)) return null;
  const choice = { day: 1 as const, targetId },
    membership = createVictoryComponent([{ kind: "faction", faction: target.campValue }]);
  // 最后权限检查与 owned 写入之间没有 await 或回调。
  (b.state as Pick<LonelyGirlState, "remaining">).remaining = 0;
  (b.state as Pick<LonelyGirlState, "choice">).choice = choice;
  b.world.addComponent(b.actorId, COMPONENT.Victory, membership);
  b.choice = Object.freeze({ ...choice });
  b.membership = target.campValue;
  b.status = "complete";
  b.isCurrent = null;
  return target.campValue;
}
export function closeLonelyGirlChoice(b: LonelyGirlBinding, status: "failed" | "cancelled"): void {
  if (b.status === "complete") return;
  b.status = status;
  b.isCurrent = null;
  for (const [key, value] of [
    ["remaining", 0],
    ["choice", null],
  ] as const) {
    const d = Object.getOwnPropertyDescriptor(b.state, key);
    if (d && Object.hasOwn(d, "value") && d.writable)
      Object.defineProperty(b.state, key, { ...d, value });
  }
}
export function projectLonelyGirl(
  world: World,
  role: RoleComponent,
): LonelyGirlReadState | undefined {
  const b = bindings.get(world);
  if (!b || b.actor.role !== role) return undefined;
  return b.status === "complete"
    ? { ...freshLonelyGirlState(), remaining: 0, choice: b.choice && { ...b.choice } }
    : {
        ...freshLonelyGirlState(),
        remaining: (b.status === "pending" || b.status === "active") && pendingOwner(b) ? 1 : 0,
      };
}
export function projectLonelyGirlSetup(world: World) {
  const b = bindings.get(world);
  return b
    ? {
        policy: LONELY_GIRL_POLICY,
        status: b.status === "active" ? ("pending" as const) : b.status,
        actorId: b.actorId,
      }
    : undefined;
}
export function projectLonelyGirlVictory(
  world: World,
  actorId: number,
): VictoryComponent | undefined {
  const b = bindings.get(world);
  return b?.actorId === actorId
    ? createVictoryComponent(b.membership ? [{ kind: "faction", faction: b.membership }] : [])
    : undefined;
}
export function openLonelyGirlNight(world: World, day: number): () => void {
  if (!bindings.has(world)) return () => {};
  if (hasActiveLonelyGirl(world) || !lonelyGirlReady(world) || hasLonelyGirlNightCommit(world, day))
    throw new Error("lonely_girl_night_unavailable");
  const days = nights.get(world) ?? new Set<number>();
  days.add(day);
  nights.set(world, days);
  activeNights.add(world);
  return () => {
    activeNights.delete(world);
  };
}

/** 失败窗口审计使用原授权身份／资源，不读取 foreign accessor。 */
export function projectLonelyGirlAuditPlayer(world: World, id: number) {
  const b = bindings.get(world),
    p = b?.participants.get(id);
  if (!b || !p || (b.status !== "failed" && b.status !== "cancelled")) return undefined;
  const alive = p.alive.get ? p.alive.get.call(p.life) === true : p.alive.value === true;
  return {
    role: p.kind,
    camp: p.roleCamp,
    alive,
    privateState:
      id === b.actorId
        ? { lonelyGirl: { ...freshLonelyGirlState(), remaining: 0 } }
        : structuredClone(p.privateSnapshot),
  };
}
